import manifest from "./photo-manifest.json";

/**
 * Photo pipeline.
 * - Cloudinary is used when VITE_CLOUDINARY_CLOUD_NAME is configured.
 * - Otherwise the bundled local copies are used, with responsive xs/md/lg
 *   variants chosen from photo-manifest.json (generated by npm run assets).
 */
const CLOUD = import.meta.env.VITE_CLOUDINARY_CLOUD_NAME || "";

const BASE = CLOUD ? `https://res.cloudinary.com/${CLOUD}/image/upload` : "";
const FALLBACK_WIDTH = 1600;

/** Pick the smallest local variant that covers the requested pixel width. */
function localUrl(photo, target) {
  const entry = manifest[photo.local];
  if (!entry?.variants?.length) return photo.local;
  const hit = entry.variants.find((variant) => variant.w >= target);
  return hit ? hit.src : photo.local;
}

/**
 * Build a transformed Cloudinary URL for a photo object { local, cloud }.
 * Locally, returns the best bundled variant for the requested size.
 * @param {{local: string, cloud: string}} photo
 * @param {{w?: number, h?: number, crop?: string, gravity?: string, dpr?: number}} opts
 */
export function photoUrl(photo, opts = {}) {
  if (!photo) return "";
  const { w, h, crop = "fill", gravity = "auto", dpr = 1 } = opts;
  if (!CLOUD) return localUrl(photo, (w || FALLBACK_WIDTH) * dpr);

  const parts = ["f_auto", "q_auto", "c_" + crop];
  if (gravity) parts.push("g_" + gravity);
  if (w) parts.push("w_" + Math.round(w * dpr));
  if (h) parts.push("h_" + Math.round(h * dpr));
  if (dpr > 1) parts.push(`dpr_${dpr}`);
  return `${BASE}/${parts.join(",")}/${photo.cloud}`;
}

/** Responsive srcset (1x/2x) for <img srcSet>. */
export function photoSrcSet(photo, { w, h, crop, gravity } = {}) {
  if (!photo) return undefined;
  const one = photoUrl(photo, { w, h, crop, gravity, dpr: 1 });
  const two = photoUrl(photo, { w, h, crop, gravity, dpr: 2 });
  return one === two ? undefined : `${one} 1x, ${two} 2x`;
}

export const cloudinaryEnabled = Boolean(CLOUD);
